describe('Rate Limit Error on Form Submission', () => {
  const RATE_LIMIT_THRESHOLD = 5;
  const RATE_LIMIT_ERROR_MESSAGE = 'Too many requests. Please try again later.';
  const FORM_SUBMIT_DELAY = 100;

  beforeEach(() => {
    cy.visit('/form');
    cy.get('form').should('be.visible');
  });

  it('should display rate limit error after exceeding submission threshold', () => {
    // Submit form multiple times to trigger rate limit
    for (let i = 0; i < RATE_LIMIT_THRESHOLD; i++) {
      cy.get('input[name="email"]').clear().type(`test${i}@example.com`);
      cy.get('button[type="submit"]').click();
      cy.wait(FORM_SUBMIT_DELAY);
    }

    // Attempt one more submission to trigger rate limit
    cy.get('input[name="email"]').clear().type('test@example.com');
    cy.get('button[type="submit"]').click();

    // Verify rate limit error is displayed
    cy.get('[data-testid="error-message"]')
      .should('be.visible')
      .and('contain', RATE_LIMIT_ERROR_MESSAGE);

    // Verify error styling
    cy.get('[data-testid="error-message"]')
      .should('have.class', 'error-alert');

    // Verify submit button is disabled
    cy.get('button[type="submit"]')
      .should('be.disabled');
  });

  it('should recover from rate limit after waiting for cooldown period', () => {
    // Submit form to trigger rate limit
    for (let i = 0; i < RATE_LIMIT_THRESHOLD + 1; i++) {
      cy.get('input[name="email"]').clear().type(`test${i}@example.com`);
      cy.get('button[type="submit"]').click();
      cy.wait(FORM_SUBMIT_DELAY);
    }

    // Verify rate limit error is shown
    cy.get('[data-testid="error-message"]')
      .should('contain', RATE_LIMIT_ERROR_MESSAGE);

    // Wait for cooldown period (simulating server-side rate limit reset)
    cy.wait(5000);

    // Refresh or reset the form state
    cy.reload();
    cy.get('form').should('be.visible');

    // Verify form is functional again
    cy.get('input[name="email"]').clear().type('valid@example.com');
    cy.get('button[type="submit"]').should('not.be.disabled');
    cy.get('button[type="submit"]').click();

    // Verify success message appears (not rate limit error)
    cy.get('[data-testid="success-message"]')
      .should('be.visible')
      .and('contain', 'Form submitted successfully');

    cy.get('[data-testid="error-message"]')
      .should('not.exist');
  });

  it('should show rate limit warning before hard limit is reached', () => {
    // Submit form near the threshold
    for (let i = 0; i < RATE_LIMIT_THRESHOLD - 1; i++) {
      cy.get('input[name="email"]').clear().type(`test${i}@example.com`);
      cy.get('button[type="submit"]').click();
      cy.wait(FORM_SUBMIT_DELAY);
    }

    // Verify warning message appears
    cy.get('[data-testid="warning-message"]')
      .should('be.visible')
      .and('contain', 'You have limited requests remaining');

    // Form should still be functional
    cy.get('button[type="submit"]').should('not.be.disabled');
  });

  it('should handle concurrent submission attempts gracefully', () => {
    // Attempt rapid consecutive submissions
    cy.get('input[name="email"]').clear().type('test@example.com');

    for (let i = 0; i < RATE_LIMIT_THRESHOLD + 2; i++) {
      cy.get('button[type="submit"]').click({ force: true });
    }

    // Verify only one error message is displayed (not multiple)
    cy.get('[data-testid="error-message"]')
      .should('have.length', 1)
      .and('contain', RATE_LIMIT_ERROR_MESSAGE);

    // Verify form state is consistent
    cy.get('form').should('have.class', 'rate-limited');
  });
});
